        body: `■ 減っているそばから増える
牛 1 頭が 1 日に食べる量を 1 とします。14 頭なら 1 日に 14 食べますが、その間に草が 2 伸びるので、**実際に減るのは 14 − 2 ＝ 12**。初めの草 60 を 12 ずつ減らして 60÷12 ＝ **5 日**。「草の量 ÷ 食べる量」（60÷14）でないのは、食べている間も草が増えるからです。

■ 伸びる量は「2 つの条件の差」から
12 頭 6 日で食べつくす → 6 日で食べた総量 12×6 ＝ 72 ＝ 初めの草 ＋ 6 日分の伸び。8 頭 10 日 → 80 ＝ 初めの草 ＋ 10 日分の伸び。**初めの草は同じ**なので、差 80 − 72 ＝ 8 が 4 日分の伸び → **1 日 2**。初めの草 ＝ 72 − 6×2 ＝ **60**。「食べた総量 ＝ 初め ＋ 伸び」の式を 2 本並べて引く——消去算と同じです。

■ 7 頭なら、2 頭なら
7 頭：実際に減るのは 7 − 2 ＝ 5 → 60÷5 ＝ **12 日**（ひっかけの 72÷7 は伸びを無視）。2 頭：食べる 2 ＝ 伸びる 2 で **草は 60 のまま減らず、食べつくせない**。ひっかけの 60÷2 ＝ 30 日は伸びを忘れています。**食べる速さが伸びる速さより大きくないと、いつまでも終わらない**。

■ 手順
①1 頭 1 日の量を 1 とする ②条件ごとに「食べた総量 ＝ 初め ＋ 日数 × 伸び」③2 本の差から 1 日の伸び、初めの量 ④新しい頭数で「実際に減る量 ＝ 食べる − 伸び」⑤初め ÷ 実際に減る量 ＝ 日数。

★ ここがポイント：ニュートン算は**「食べた総量 ＝ 初めの量 ＋ 日数 × 伸び」を 2 本並べて引き**、伸び（1 日 2）と初めの量（60）を出す。日数は**初め ÷（食べる量 − 伸びる量）**（14 頭：60÷12 ＝ 5 日）。伸びを無視した 72÷7 や 60÷2 は誤り。食べる ≦ 伸びる なら終わらない。`,
