        body: `仕事算は「全体の仕事量を1とおいて、1日（1時間）あたりにできる仕事量（＝速さ）」を考える問題です。日数ではなく「速さ」を足し算するのが鉄則です。

■ 例題①
ある仕事をAさん1人ですると6日、Bさん1人ですると3日かかる。2人で一緒にすると何日で終わるか。

【解法】
　全体の仕事量を1とする。
　Aの1日の仕事量 ＝ 1÷6 ＝ 1/6
　Bの1日の仕事量 ＝ 1÷3 ＝ 1/3
　2人合わせた1日の仕事量 ＝ 1/6＋1/3 ＝ 1/6＋2/6 ＝ 3/6 ＝ 1/2
　日数 ＝ 1÷(1/2) ＝ 2日

■ 例題②
Aさん1人で6日、Bさん1人で12日かかる仕事を、2人で一緒にすると何日で終わるか。

【解法】
　Aの1日の仕事量＝1/6、Bの1日の仕事量＝1/12
　2人合わせて ＝ 1/6＋1/12 ＝ 2/12＋1/12 ＝ 3/12 ＝ 1/4
　日数 ＝ 1÷(1/4) ＝ 4日

★ ポイント：「日数」ではなく「1日あたりの仕事量（速さ）」が足し算できる量です。この違いを常に意識しましょう。`,
