        figureId: 'sext10_s357_naze',
        body: `■ 足せるのは「同じ時間にする量」
A が 6 日、B が 12 日かかる仕事を 2 人でやると、**1 日に進む量が A の分と B の分の合計**になります。全体を 1 とすると A は 1 日に 1/6、B は 1/12 進むので、2 人で 1/6 ＋ 1/12 ＝ 3/12 ＝ 1/4。1 日に 1/4 進むなら 4 日で終わる。日数の 6 と 12 は「かかる時間」で、足しても平均しても意味がありません（(6 ＋ 12)÷2 ＝ 9 日は、1 人でやるより遅くなってしまい、あり得ない）。

■ 分数がいやなら「全体を 12」に
6 と 12 の最小公倍数 12 を全体の仕事量にすると、A は 1 日 2、B は 1 日 1、2 人で 3。12÷3 ＝ **4 日**。**「全体を 1」も「全体を最小公倍数」も同じ考え方**で、分数なしで計算できます。

■ 「1/3 日」のひっかけ
A 4 日・B 12 日で 2 人の 1 日の仕事量は 1/4 ＋ 1/12 ＝ 1/3。これは「1 日に全体の 1/3 進む」という**速さ**で、日数ではありません。日数は 1÷(1/3) ＝ **3 日**。**速さと時間を取りちがえない**——「1 日に 1/3」なら 3 日で 1 になる、と言葉で確かめます。

■ 2 人でやると必ず速い
2 人の日数は、速いほうの 1 人（A の 6 日）より必ず短い（4 日）。9 日のように 1 人より長くなったら計算ちがい。

■ 手順
①全体を 1（または最小公倍数）②1 日の仕事量 ＝ 全体 ÷ 日数 ③2 人分を足す ④全体 ÷ 2 人の 1 日の量 ＝ 日数 ⑤速いほうの 1 人より短いか確かめる。

★ ここがポイント：足せるのは**「1 日に進む量」**（1/6 ＋ 1/12 ＝ 1/4 → 4 日）で、日数（6 ＋ 12）ではない。全体を最小公倍数 12 にすれば 2 ＋ 1 ＝ 3、12÷3 ＝ 4 日。**1/3 は「1 日に進む量」で日数ではない**（3 日）。2 人なら速いほうの 1 人より必ず短い。`,
